var bidMatch = baseUrl.match(/read\/(\d+)/);
if (!bidMatch) {
    [];
} else {
    var bid = bidMatch[1];
    var resp = java.post(source.getKey() + "/novel/clist/", "bid=" + bid, {});
    var json = JSON.parse(resp.body()).data;
    var result = [];
    var volume = "";
    for (var i = 0; i < json.length; i++) {
        var item = json[i];
        if (item.ctype === "1") {
            volume = item.title;
            continue;
        }
        item.url = source.getKey() + "/read/" + bid + "/p" + item.ordernum + ".html";
        item.volume = volume;
        result.push(item);
    }
    result;
}

